from django.db import migrations, models
from django.db.models import F

# Written here rather than read from game.balance: a migration must do the
# same thing forever, whatever the balance becomes.
MAX_UNITS = 50


def to_slots(apps, schema_editor):
    """
    The feeder was {resource: quantity}; it becomes a list of slots
    [[resource, units], ...]. Each resource becomes a slot of at most
    MAX_UNITS units: what is above goes back to the player's stock.
    """
    Player = apps.get_model("ranch", "Player")
    ResourceStock = apps.get_model("ranch", "ResourceStock")
    for player in Player.objects.exclude(feeder=[]):
        if isinstance(player.feeder, list):
            continue  # already slots
        slots = []
        for resource, quantity in player.feeder.items():
            units = min(quantity, MAX_UNITS)
            slots.append([resource, units])
            if quantity > units:
                stock, _ = ResourceStock.objects.get_or_create(player=player, resource=resource)
                ResourceStock.objects.filter(pk=stock.pk).update(
                    amount=F("amount") + quantity - units
                )
        player.feeder = slots
        player.save(update_fields=["feeder"])


